#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> precomputedFactorials;

long long quickPow(long long base, long long exp) {
    long long res = 1LL;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long choose(int n, int r) {
    if (r == 0 || r == n) return 1LL;
    if (r > n || r < 0) return 0LL;
    long long numerator = precomputedFactorials[n];
    long long denominator = (precomputedFactorials[r] * precomputedFactorials[n - r]) % MOD;
    return (numerator * quickPow(denominator, MOD - 2)) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    precomputedFactorials.resize(n + 1);
    precomputedFactorials[0] = 1LL;
    for (int i = 1; i <= n; i++) {
        precomputedFactorials[i] = (precomputedFactorials[i - 1] * i) % MOD;
    }
    if (k == 0) {
        cout << precomputedFactorials[n] << "\n";
    } else if (k >= n) {
        cout << 0 << "\n";
    } else {
        int m = (int)k;
        long long sumResult = 0LL;
        long long sign = 1LL;
        int l = n - m;
        for (int i = 0; i <= l; i++) {
            long long term = (quickPow(l - i, n) * choose(l, l - i)) % MOD;
            sumResult = (sumResult + sign * term + MOD) % MOD;
            sign *= -1LL;
        }
        long long finalRes = (2LL * choose(n, m) * sumResult) % MOD;
        cout << finalRes << "\n";
    }
    return 0;
}
